 ('pizza','Chicken Tikka Pizza','/menu/items/pizza-chicken-tikka.png'),('pizza','Chicken Fajita Pizza','/menu/items/pizza-chicken-fajita.png'),('pizza','Chicken Tandoori Pizza','/menu/items/pizza-chicken-tandoori.png'),('pizza','Chicken Achar Pizza','/menu/items/pizza-chicken-achar.png'),('pizza','Pizza Point Special','/menu/items/pizza-point-special.png'),('pizza','Malai Botti','/menu/items/pizza-malai-botti.png'),('pizza','Chicken Lover','/menu/items/pizza-chicken-lover.png'),('pizza','Donner Pizza','/menu/items/pizza-donner.png'),('pizza','Labnani Pizza','/menu/items/pizza-labnani.png'),('pizza','Crown Crust Pizza','/menu/items/pizza-crown-crust.png'),('pizza','Crown Kabab Crust Pizza','/menu/items/pizza-crown-kabab-crust.png'),('pizza','Stuff Kabab Pizza','/menu/items/pizza-stuff-kabab.png'),('pizza','Stuff Cheese Pizza','/menu/items/pizza-stuff-cheese.png'),('pizza','Extra Topping / Cheese Crust','/menu/items/pizza-stuff-cheese.png'),
 ('burgers','Zinger Burger','/menu/items/burger-zinger.png'),('burgers','Zinger Burger with Cheese','/menu/items/burger-zinger.png'),('burgers','Chicken Petty Burger','/menu/items/burger-chicken-patty.png'),('burgers','Chicken Petty Burger Cheese','/menu/items/burger-chicken-patty.png'),('burgers','Chicken Tower Burger','/menu/items/burger-chicken-tower.png'),('burgers','Chicken Tower Cheese Burger','/menu/items/burger-chicken-tower.png'),('burgers','Double Decker Cheese Burger','/menu/items/burger-double-decker.png'),
 ('shawarma','Chicken Shawarma','/menu/items/shawarma-chicken.png'),('shawarma','Chicken Cheese Shawarma','/menu/items/shawarma-chicken.png'),('shawarma','Zinger Shawarma','/menu/items/shawarma-zinger.png'),('shawarma','Zinger Cheese Shawarma','/menu/items/shawarma-zinger.png'),('shawarma','Seekh Kabab Shawarma','/menu/items/shawarma-seekh-kabab.png'),('shawarma','Seekh Kabab Cheese Shawarma','/menu/items/shawarma-seekh-kabab.png'),('shawarma','Vegetable Shawarma','/menu/items/shawarma-vegetable.png'),
 ('paratha-rolls','Chicken Paratha','/menu/items/paratha-chicken.png'),('paratha-rolls','Chicken Cheese Paratha','/menu/items/paratha-chicken.png'),('paratha-rolls','Zinger Paratha','/menu/items/paratha-zinger.png'),('paratha-rolls','Zinger Cheese Paratha','/menu/items/paratha-zinger.png'),('paratha-rolls','Seekh Kabab Paratha','/menu/items/paratha-seekh-kabab.png'),('paratha-rolls','Seekh Kabab Cheese Paratha','/menu/items/paratha-seekh-kabab.png'),
 ('pasta','Crispy Crunchy Pasta','/menu/items/pasta-crispy-crunchy.png'),('pasta','Creamy Pasta','/menu/items/pasta-creamy.png')
)
